frappe.ui.form.on('Item', {
    before_save: async function (frm) {
        if (!frm.is_new()) return;

        if (frm.doc.is_fixed_asset) {
            await generate_fixed_item_code(frm);
        } else {
            await generate_normal_item_code(frm);
        }
    }
});

async function generate_normal_item_code(frm) {
    console.log("sth...")
    if (!frm.doc.custom_prefix) {
        await frm.set_value('custom_prefix', 'MAIN');
    }

    if (!frm.doc.custom_sub_prefix) {
        await frm.set_value('custom_sub_prefix', 'SUB');
    }

    const res = await frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Item",
            filters: {
                custom_prefix: frm.doc.custom_prefix,
                custom_sub_prefix: frm.doc.custom_sub_prefix
            },
            fields: ["custom_item_no"],
            order_by: "creation desc",
            limit_page_length: 1
        }
    });

    let last_number = 0;
    if (res.message && res.message.length) {
        last_number = parseInt(res.message[0].custom_item_no) || 0;
    }

    const item_number = last_number + 1;
    await frm.set_value('custom_item_no', item_number);

    const new_code = `${frm.doc.custom_prefix}-${frm.doc.custom_sub_prefix}-${String(item_number).padStart(4, '0')}`;
    await frm.set_value('item_code', new_code);
}

async function generate_fixed_item_code(frm) {
    if (!frm.doc.asset_category || !frm.doc.custom_asset_sub_category) {
        frappe.throw("Asset Category and Sub Category are required");
    }

    // Get Asset Category Code
    const cat = await frappe.db.get_value(
        "Asset Category",
        frm.doc.asset_category,
        "custom_asset_category_code"
    );

    if (!cat.message || !cat.message.custom_asset_category_code) {
        frappe.throw("Asset Category Code is missing");
    }

    // Get Asset Sub Category Code
    const sub = await frappe.db.get_value(
        "Asset Sub Category",
        frm.doc.custom_asset_sub_category,
        "code"
    );

    if (!sub.message || !sub.message.code) {
        frappe.throw("Asset Sub Category Code is missing");
    }

    const prefix = `${cat.message.custom_asset_category_code}${sub.message.code}-`;

    // Get last fixed asset item
    const res = await frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Item",
            filters: {
                is_fixed_asset: 1,
                item_code: ["like", prefix + "%"]
            },
            fields: ["item_code"],
            order_by: "item_code desc",
            limit_page_length: 1
        }
    });

    let next_number = 1;
    if (res.message && res.message.length) {
        const match = res.message[0].item_code.match(/-(\d+)$/);
        if (match) {
            next_number = parseInt(match[1]) + 1;
        }
    }

    const final_code = prefix + String(next_number).padStart(4, "0");
    await frm.set_value("item_code", final_code);
}

