frappe.ui.form.on("Stock Entry Detail", {
	custom_fuel_request(frm, cdt, cdn) {
	    console.log("abebeb")
		let row = locals[cdt][cdn];
		if (row.custom_fuel_request) {
			frappe.call({
				method: "equipment_and_maintenance.equipment.doctype.fuel_request.fuel_request.get_fuel_request_data",
				args: {
					fuel_request: row.custom_fuel_request
				},
				callback: function(r) {
					if (r.message && Object.keys(r.message).length > 0) {
						let data = r.message;
						console.log("data", data)

						if (data.item_code) {
							frappe.model.set_value(cdt, cdn, "item_code", data.item_code);
						}
						if (data.qty) {
							frappe.model.set_value(cdt, cdn, "qty", data.qty);
						}
						if (data.basic_rate) {
							frappe.model.set_value(cdt, cdn, "basic_rate", data.basic_rate);
						}
						if (data.amount !== undefined) {
							frappe.model.set_value(cdt, cdn, "amount", data.amount);
						}
						if (data.custom_current_kmhr_reading !== undefined) {
							frappe.model.set_value(cdt, cdn, "custom_current_kmhr_reading", data.custom_current_kmhr_reading);
						}
						if (data.custom_previous_kmhr_reading !== undefined) {
							frappe.model.set_value(cdt, cdn, "custom_previous_kmhr_reading", data.custom_previous_kmhr_reading);
						}
						if (data.custom_kmhr_difference !== undefined) {
							frappe.model.set_value(cdt, cdn, "custom_kmhr_difference", data.custom_kmhr_difference);
						}
						if (data.custom_plate_no) {
							frappe.model.set_value(cdt, cdn, "custom_plate_no", data.custom_plate_no);
						}

						frm.refresh_field("items");
					}
				}
			});
		}
	}
});

