frappe.ui.form.on("Stock Entry", {
	refresh(frm) {
		// Add "Fuel Request" button under "Get Items From" only for Fuel and Lubricant Distribution Voucher
		if (frm.doc.docstatus === 0 && frm.doc.stock_entry_type === "Fuel and Lubricant Distribution Voucher") {
			frm.add_custom_button(
				__("Fuel Request"),
				function() {
					erpnext.utils.map_current_doc({
						method: "equipment_and_maintenance.equipment.doctype.fuel_request.fuel_request.make_stock_entry",
						source_doctype: "Fuel Request",
						target: frm,
						date_field: "date",
						setters: {},  // Empty setters object to prevent undefined error
						get_query: function() {
							return {
								filters: {
									docstatus: 1,  // Only submitted Fuel Requests
									status: ["!=", "Distributed"]  // Exclude already distributed
								}
							};
						},
					});
				},
				__("Get Items From")
			);
		} else {
			// Remove button if not applicable
			frm.remove_custom_button(__("Fuel Request"), __("Get Items From"));
		}
	},

	stock_entry_type(frm) {
		// Refresh to show/hide the button
		frm.trigger("refresh");
	}
});
